// 2. Validate Input
// Confirms the routing decision handed off by WF-06 has what the
// notification dispatcher needs to prepare and route a payload.

const item = $input.first().json;

const incidentId = item.incidentId;
const siteId = item.siteId;
const assignedTeam = item.assignedTeam;
const priority = item.priority;
const notificationPolicy = item.notificationPolicy;

const missing = [];
if (!incidentId) missing.push('incidentId');
if (!siteId) missing.push('siteId');
if (!assignedTeam) missing.push('assignedTeam');
if (!priority) missing.push('priority');
if (!notificationPolicy) missing.push('notificationPolicy');

return [{
  json: {
    isValid: missing.length === 0,
    missingFields: missing,
    ...item
  }
}];

// 3. Resolve Notification Destination & Channel
// Maps the incident's assigned team to a Telegram chat destination
// using a team -> chat mapping table (same pattern as WF-06's Business
// Rule Matrix). Teams without an explicit mapping fall back to the NOC
// default chat rather than leaving the incident undeliverable. Channel
// is fixed to 'telegram' for this milestone; additional channels are a
// future milestone's concern, not this workflow's.
//
// Chat IDs below are placeholders. Replace each with the real Telegram
// chat/group ID before this feeds the telegram-notifier workflow.

const item = $input.first().json;

const assignedTeam = item.assignedTeam;

const TEAM_CHAT_MAP = {
  'Transmission Team': 'TELEGRAM_CHAT_TRANSMISSION_TEAM',
  'Power Team': 'TELEGRAM_CHAT_POWER_TEAM',
  'Access Network Team': 'TELEGRAM_CHAT_ACCESS_NETWORK_TEAM',
  'IP Network Team': 'TELEGRAM_CHAT_IP_NETWORK_TEAM',
  'IP Core Team': 'TELEGRAM_CHAT_IP_CORE_TEAM',
  'Transmission Monitoring': 'TELEGRAM_CHAT_TRANSMISSION_MONITORING',
  'Site Maintenance Team': 'TELEGRAM_CHAT_SITE_MAINTENANCE_TEAM',
  'NOC': 'TELEGRAM_CHAT_NOC'
};

const DEFAULT_CHAT = 'TELEGRAM_CHAT_NOC';

const destinationMatched = Object.prototype.hasOwnProperty.call(TEAM_CHAT_MAP, assignedTeam);
const chatId = destinationMatched ? TEAM_CHAT_MAP[assignedTeam] : DEFAULT_CHAT;

return [{
  json: {
    ...item,
    channel: 'telegram',
    chatId,
    destinationMatched
  }
}];

// 4. Build Notification Payload
// Composes the human-readable Telegram message and assembles the final
// structured output. Does NOT send anything -- WF-07 only prepares and
// routes the notification payload. Delivery is a separate workflow
// (telegram-notifier) planned for the next milestone. Defaults
// gracefully when optional upstream fields are missing, matching
// WF-06's philosophy of never blocking on a partial incident.

const item = $input.first().json;

const incidentId = item.incidentId;
const correlationId = item.correlationId || null;
const siteId = item.siteId;
const assignedTeam = item.assignedTeam;
const priority = item.priority;
const notificationPolicy = item.notificationPolicy;
const escalationLevel = item.escalationLevel || 'L2';
const immediateEscalation = item.immediateEscalation === true;
const slaDeadline = item.slaDeadline || null;
const businessImpact = item.businessImpact || 'Business impact not available';
const affectedCustomers = typeof item.affectedCustomers === 'number' ? item.affectedCustomers : 0;
const chatId = item.chatId;
const channel = item.channel || 'telegram';
const destinationMatched = item.destinationMatched === true;

const urgencyMarker = immediateEscalation ? '\uD83D\uDEA8 IMMEDIATE ESCALATION \uD83D\uDEA8\n' : '';

const messageTitle = urgencyMarker + '[' + priority + '] Incident ' + incidentId;

const messageBody =
  'Team: ' + assignedTeam + '\n' +
  'Priority: ' + priority + ' (' + notificationPolicy + ')\n' +
  'Escalation: ' + escalationLevel + '\n' +
  'SLA Deadline: ' + (slaDeadline || 'not set') + '\n' +
  'Site: ' + siteId + '\n' +
  'Impact: ' + businessImpact;

return [{
  json: {
    incidentId,
    correlationId,
    siteId,
    channel,
    destination: {
      team: assignedTeam,
      chatId,
      destinationMatched
    },
    priority,
    notificationPolicy,
    escalationLevel,
    immediateEscalation,
    messageTitle,
    messageBody,
    slaDeadline,
    businessImpact,
    affectedCustomers,
    dispatchStatus: 'ready_for_dispatch',
    preparedAt: new Date().toISOString(),
    nextWorkflow: 'telegram-notifier'
  }
}];
